def js(s): return "'" + s.replace('\\','\\\\').replace("'","\\'") + "'"
# shared.js inline ro/en: după linia syncProfiles din fiecare bloc
p = root/'extension/shared.js'; src = p.read_text(encoding='utf8')
for lg in ('ro','en'):
    if "m_modules2:" in src and lg == 'ro' and src.count('m_modules2:') >= 2: break
lines = src.split('\n'); out = []; seen = 0
for ln in lines:
    out.append(ln)
    if re.match(r"\s+syncProfiles: '", ln):
        lg = 'ro' if seen == 0 else 'en'; seen += 1
        ind = re.match(r'\s+', ln).group()
        if "m_modules2:" not in src:
            out.extend(ind + key + ': ' + js(v[lg]) + ',' for key, v in K.items())
if 'm_modules2:' not in src: p.write_text('\n'.join(out), encoding='utf8')
# fix trailing comma issue: lista se termină cu virgulă înaintea următoarei chei, ok
for lg in ['de','es','fr','hu','it','pt']:
    jp = root/'extension/lang'/(lg+'.json'); d = json.loads(jp.read_text(encoding='utf8'))
    d.update({key: v[lg] for key, v in K.items()})
    jp.write_text(json.dumps(d, ensure_ascii=False, indent=0), encoding='utf8')
    tp = root/'i18n_src'/(lg+'.txt')
    if tp.exists():
        t = tp.read_text(encoding='utf8'); have = {l.split('=',1)[0] for l in t.split('\n') if '=' in l}
        add = ''.join(f"{key}={v[lg]}\n" for key, v in K.items() if key not in have)
        if add: tp.write_text(t.rstrip('\n') + '\n' + add, encoding='utf8')
